<script setup lang="ts">
import { computed, ref, watch, onMounted, onBeforeUnmount } from 'vue'
import { RouterLink } from 'vue-router'
import { ArrowUpRight, BookOpen, CalendarDays, GraduationCap, Clock3, Users, CheckCircle2, ClipboardList, Layers, Bell, ShieldCheck, ChartColumn } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatCard from '../components/StatCard.vue'
import StatePanel from '../components/StatePanel.vue'
import { api, query, type Dashboard, type StudentSummary, type Enrollment, type Section, type Round, type Notification, type Page } from '../lib/api'
import { useAuth } from '../stores/auth'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'
import { formatTime } from '../lib/format'
import { isRoundOpen } from '../lib/rounds'

const auth = useAuth(), workspace = useWorkspace(), { loading, error, run } = useAsync()
const dashboard = ref<Dashboard>(), summary = ref<StudentSummary>(), enrollments = ref<Enrollment[]>([]), sections = ref<Section[]>([]), rounds = ref<Round[]>([]), notices = ref<Notification[]>([])
const student = computed(() => auth.user?.role === 'STUDENT'), teacher = computed(() => auth.user?.role === 'TEACHER')
const now = ref(Date.now())
const activeRound = computed(() => rounds.value.find(round => isRoundOpen(round, now.value)))
let clock: ReturnType<typeof setInterval> | undefined
onMounted(() => { clock = setInterval(() => { now.value = Date.now() }, 15000) })
onBeforeUnmount(() => { if (clock) clearInterval(clock) })
async function load() { await run(async () => { const suffix = query({ termId: workspace.termId }); const result = await Promise.all([api<Dashboard>('/dashboard' + suffix), api<Page<Round>>('/rounds' + suffix), api<Page<Notification>>('/notifications?size=3')]); dashboard.value = result[0]; rounds.value = result[1].items; notices.value = result[2].items; if (student.value) { const [s, e] = await Promise.all([api<StudentSummary>('/student/summary' + suffix), api<Page<Enrollment>>('/student/enrollments' + query({ termId: workspace.termId, size: 5 }))]); summary.value = s; enrollments.value = e.items } else { sections.value = (await api<Page<Section>>((teacher.value ? '/teacher/sections' : '/admin/sections') + query({ termId: workspace.termId, size: 5 }))).items } }) }
watch(() => workspace.termId, load, { immediate: true })
const links = computed(() => student.value ? [{ to: '/student/catalog', title: '寻找心仪课程', sub: '发现下一段学习旅程', icon: BookOpen }, { to: '/student/timetable', title: '查看每周课表', sub: '把时间安排得刚刚好', icon: CalendarDays }, { to: '/student/courses', title: '管理我的课程', sub: '选课、换班与候补进度', icon: Layers }, { to: '/student/grades', title: '回顾学习收获', sub: '已发布成绩与通过学分', icon: GraduationCap }] : teacher.value ? [{ to: '/teacher/sections', title: '我的授课班级', sub: '班级名单与教学安排', icon: Users }, { to: '/teacher/sections', title: '成绩工作台', sub: '草稿保存与成绩发布', icon: ClipboardList }, { to: '/notifications', title: '查看教学消息', sub: '及时了解教学动态', icon: Bell }, { to: '/profile', title: '我的教师档案', sub: '查看账户与身份信息', icon: GraduationCap }] : [{ to: '/admin/manage', title: '管理教学安排', sub: '课程、排课与选课轮次', icon: BookOpen }, { to: '/admin/enrollments', title: '选课与候补', sub: '查看名额与有序递补', icon: Users }, { to: '/admin/analytics', title: '阅读教学数据', sub: '从真实数据发现变化', icon: ChartColumn }, { to: '/admin/audit', title: '追溯操作记录', sub: '重要变更都有迹可循', icon: ShieldCheck }])
</script>
<template><PageHeading eyebrow="YOUR SEMESTER, THOUGHTFULLY ORGANIZED" :title="`${auth.user?.displayName || '你'}，很高兴见到你`" :description="student ? '新学期的每一次选择，都在构建属于你的未来。' : teacher ? '让教学安排更清晰，让每一份成长被认真看见。' : '从教学安排到每一次选课，让教务工作井然有序。'"><label class="sr-only" for="overview-term">查看学期</label><select id="overview-term" v-model="workspace.termId" class="select-control"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select></PageHeading><StatePanel v-if="loading && !dashboard" loading/><StatePanel v-else-if="error" :error="error" @retry="load"/><template v-else-if="dashboard"><section class="stats-grid" aria-label="当前学期概况"><StatCard :label="student ? '当前已选课程' : teacher ? '正在授课的班级' : '在册学生'" :value="student ? dashboard.enrollments : teacher ? dashboard.sections : dashboard.students" :note="student ? '每一门，都是新的可能' : '当前学期 · 实时统计'"><BookOpen/></StatCard><StatCard :label="student ? '已选学分' : teacher ? '班级选课人数' : '开设教学班'" :value="student ? `${summary?.selectedCredits ?? 0} / ${summary?.creditLimit ?? '—'}` : teacher ? dashboard.enrollments : dashboard.sections" :note="student ? '当前选课 / 学期上限' : '实际选课记录'"><Layers/></StatCard><StatCard :label="student ? '累计已通过学分' : '等待候补人数'" :value="student ? summary?.earnedCredits ?? '—' : dashboard.waiting" :note="student ? '已发布且成绩达到60分' : '按入队顺序有序等待'"><GraduationCap/></StatCard><StatCard :label="student ? '我的候补' : '已发布成绩均分'" :value="student ? summary?.waitingCount ?? 0 : dashboard.averageGrade == null ? '—' : Number(dashboard.averageGrade).toFixed(1)" :note="student ? '递补结果会通过消息通知' : '只统计已发布成绩'" accent><Clock3/></StatCard></section><div class="welcome-grid"><section class="hero-panel"><p class="eyebrow">{{ workspace.currentTerm?.name || 'NEW SEMESTER' }}</p><h2>{{ student ? '为热爱留一个位置。' : teacher ? '用认真，回应每一份努力。' : '好的秩序，让成长自然而然。' }}</h2><p>{{ student ? '看清课程安排、先修条件和可选名额，找到适合自己的学习节奏。' : teacher ? '班级名单、成绩草稿与正式发布，在一个工作台里清晰完成。' : '课程、教学班、选课轮次与成绩，构成完整而可追溯的教学链路。' }}</p><RouterLink :to="student ? '/student/catalog' : teacher ? '/teacher/sections' : '/admin/manage'" class="button">{{ student ? '前往选课中心' : teacher ? '进入授课工作台' : '查看教学安排' }}<ArrowUpRight :size="14"/></RouterLink><div class="hero-meta"><span><CalendarDays :size="12"/>{{ workspace.currentTerm?.name || '学期加载中' }}</span><span><CheckCircle2 :size="12"/>{{ activeRound ? `${activeRound.name} · 开放中` : '当前无开放的选课轮次' }}</span></div></section><section class="quick-links" aria-label="常用入口"><RouterLink v-for="link in links" :key="link.to + link.title" :to="link.to" class="quick-link"><component :is="link.icon"/><div><strong>{{ link.title }}</strong><small>{{ link.sub }}</small></div><ArrowUpRight :size="13" class="spacer"/></RouterLink></section></div><div class="content-columns"><section class="card"><div class="card-header"><div><h2>{{ student ? '我的学习安排' : teacher ? '正在授课的班级' : '教学班概览' }}</h2><p>{{ student ? '已选课程与本学期的学习计划' : '当前学期的课程安排与选课容量' }}</p></div><RouterLink :to="student ? '/student/courses' : teacher ? '/teacher/sections' : '/admin/enrollments'" class="text-button">查看全部<ArrowUpRight :size="12"/></RouterLink></div><StatePanel v-if="student ? !enrollments.length : !sections.length" title="新的学期，等待开始" :description="student ? '前往选课中心，寻找你的第一门心仪课程。' : '建立教学班后，教学安排会在这里呈现。'"/><div v-else class="table-wrap"><table><caption class="sr-only">{{ student ? '已选课程' : '教学班' }}</caption><thead><tr><th>课程 / 教学班</th><th>授课教师</th><th>{{ student ? '学分' : '选课人数' }}</th><th>状态</th></tr></thead><tbody><template v-if="student"><tr v-for="item in enrollments" :key="item.id"><td><strong>{{ item.courseTitle }}</strong><small>{{ item.sectionId }}</small></td><td>{{ item.teacherName }}</td><td>{{ item.credits }} 学分</td><td><span class="tag">{{ item.grade != null ? '成绩已发布' : '学习进行中' }}</span></td></tr></template><template v-else><tr v-for="item in sections" :key="item.id"><td><strong>{{ item.courseTitle }}</strong><small>{{ item.id }}</small></td><td>{{ item.teacherName }}</td><td>{{ item.enrolledCount }} / {{ item.capacity }}<span class="progress-track"><span :style="{ width: `${item.capacity ? item.enrolledCount / item.capacity * 100 : 0}%` }"/></span></td><td><span class="tag" :class="{ 'tag-gold': item.enrolledCount >= item.capacity }">{{ item.enrolledCount >= item.capacity ? '名额已满' : '有剩余名额' }}</span></td></tr></template></tbody></table></div></section><aside class="aside-column"><div class="aside-card"><div class="aside-icon"><CalendarDays :size="19"/></div><h3>重要的时间，<br>值得提前记下。</h3><template v-if="activeRound"><p>{{ activeRound.name }}</p><div class="mini-timeline"><div class="timeline-item"><strong>选课开放</strong><p>{{ formatTime(activeRound.startsAt) }}</p></div><div class="timeline-item"><strong>选课截止</strong><p>{{ formatTime(activeRound.endsAt) }}</p></div><div class="timeline-item"><strong>退课截止</strong><p>{{ formatTime(activeRound.withdrawalEndsAt) }}</p></div></div></template><p v-else>当前没有开放的选课轮次。新的安排发布后，请及时查看教务通知。</p><RouterLink to="/notifications" class="aside-link">查看消息中心<ArrowUpRight :size="12"/></RouterLink></div><section v-if="notices.length" class="card card-padding mt-20"><p class="section-label">最近消息</p><div class="mini-timeline"><div v-for="item in notices" :key="item.id" class="timeline-item"><strong>{{ item.title }}</strong><p>{{ formatTime(item.createdAt) }}</p></div></div><RouterLink to="/notifications" class="text-button mt-20">查看全部消息<ArrowUpRight :size="12"/></RouterLink></section></aside></div></template></template>
